BEGIN;
CREATE TABLE IF NOT EXISTS schema_migration (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE configuracion (clave varchar(50) PRIMARY KEY, valor numeric(12,4) NOT NULL, descripcion varchar(150));
CREATE TABLE unidad_medida (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre varchar(30) UNIQUE NOT NULL, abreviatura varchar(10) NOT NULL);
CREATE TABLE nivel_servicio (nivel numeric(4,3) PRIMARY KEY CHECK(nivel>0 AND nivel<1), z numeric(5,3) NOT NULL CHECK(z>0));
CREATE TYPE periodo_consumo AS ENUM ('diario','semanal','mensual','anual');
CREATE TABLE insumo (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre varchar(80) UNIQUE NOT NULL, descripcion varchar(200), unidad_id integer NOT NULL REFERENCES unidad_medida(id), cantidad_presentacion numeric(12,2) NOT NULL DEFAULT 1 CHECK(cantidad_presentacion>0), precio_presentacion numeric(10,2) CHECK(precio_presentacion>=0), consumo_prom numeric(12,6) NOT NULL DEFAULT 0 CHECK(consumo_prom>=0), periodo_consumo periodo_consumo NOT NULL DEFAULT 'diario', activo boolean NOT NULL DEFAULT true, categoria text NOT NULL DEFAULT 'Insumos', costo_pendiente boolean NOT NULL DEFAULT true);
CREATE TABLE parametro_inventario (insumo_id integer PRIMARY KEY REFERENCES insumo(id), demanda_diaria numeric(12,8) NOT NULL CHECK(demanda_diaria>=0), tiempo_entrega_dias numeric(6,2) NOT NULL CHECK(tiempo_entrega_dias>=0), nivel_servicio numeric(4,3) NOT NULL DEFAULT .95 REFERENCES nivel_servicio(nivel), pct_desv_demanda numeric(4,3) NOT NULL DEFAULT .15 CHECK(pct_desv_demanda>=0), tiempo_revision_dias numeric(6,2) NOT NULL DEFAULT 60 CHECK(tiempo_revision_dias>=0), inventario_actual numeric(12,6) NOT NULL DEFAULT 0 CHECK(inventario_actual>=0));
CREATE TABLE producto (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre varchar(50) UNIQUE NOT NULL, litros_unidad numeric(6,2) NOT NULL DEFAULT 0 CHECK(litros_unidad>=0), precio_venta numeric(10,2) NOT NULL CHECK(precio_venta>=0), cantidad numeric(12,6) NOT NULL DEFAULT 0 CHECK(cantidad>=0), stock_minimo numeric(12,6) NOT NULL DEFAULT 0 CHECK(stock_minimo>=0), categoria text NOT NULL DEFAULT 'Agua purificada', unidad text NOT NULL DEFAULT 'unidades', descripcion text NOT NULL DEFAULT '', activo boolean NOT NULL DEFAULT true, receta_validada boolean NOT NULL DEFAULT false);
CREATE TABLE producto_insumo (producto_id integer NOT NULL REFERENCES producto(id), insumo_id integer NOT NULL REFERENCES insumo(id), cantidad_p_unidad numeric(10,4) NOT NULL DEFAULT 1 CHECK(cantidad_p_unidad>0), PRIMARY KEY(producto_id,insumo_id));
CREATE TABLE importacion (id text PRIMARY KEY, archivo_hash text NOT NULL, anio integer NOT NULL CHECK(anio BETWEEN 2000 AND 2200), creado_en timestamptz NOT NULL DEFAULT now(), UNIQUE(archivo_hash,anio));
CREATE TABLE merma_registro (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, insumo_id integer NOT NULL REFERENCES insumo(id), fecha date, cantidad_inicial numeric(18,8) NOT NULL CHECK(cantidad_inicial>0), cantidad_final numeric(18,8) NOT NULL CHECK(cantidad_final>=0 AND cantidad_final<=cantidad_inicial), periodo_fuente text, importacion_id text REFERENCES importacion(id), UNIQUE(importacion_id,insumo_id));
CREATE TABLE venta_mensual (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, producto_id integer NOT NULL REFERENCES producto(id), anio integer NOT NULL CHECK(anio BETWEEN 2000 AND 2200), mes integer NOT NULL CHECK(mes BETWEEN 1 AND 12), unidades integer NOT NULL CHECK(unidades>=0), precio_unitario numeric(10,2) NOT NULL CHECK(precio_unitario>=0), ingreso numeric(14,2) NOT NULL CHECK(ingreso>=0), importacion_id text REFERENCES importacion(id), UNIQUE(producto_id,anio,mes));
CREATE TABLE pedido_pipa (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, anio integer NOT NULL, semana integer NOT NULL CHECK(semana BETWEEN 1 AND 53), litros_base numeric(14,6) NOT NULL DEFAULT 10000 CHECK(litros_base>=0), litros_extra numeric(14,6) NOT NULL DEFAULT 0 CHECK(litros_extra>=0), estado text NOT NULL DEFAULT 'planeado' CHECK(estado IN ('planeado','recibido')), UNIQUE(anio,semana));
CREATE TABLE proyeccion_semanal (anio integer NOT NULL, semana integer NOT NULL CHECK(semana BETWEEN 1 AND 24), unidades_garrafon integer NOT NULL CHECK(unidades_garrafon>=0), unidades_1l integer NOT NULL CHECK(unidades_1l>=0), unidades_500ml integer NOT NULL CHECK(unidades_500ml>=0), agua_neta numeric(18,8) NOT NULL, agua_disponible numeric(18,8) NOT NULL, agua_con_merma numeric(18,8) NOT NULL, litros_extra numeric(18,8) NOT NULL, litros_merma numeric(18,8) NOT NULL, costo_merma numeric(18,8) NOT NULL, yield_pct numeric(18,10) NOT NULL, importacion_id text NOT NULL REFERENCES importacion(id), PRIMARY KEY(anio,semana));
CREATE TABLE fuente_celda (importacion_id text NOT NULL REFERENCES importacion(id), hoja text NOT NULL, celda text NOT NULL, valor text, formula text, PRIMARY KEY(importacion_id,hoja,celda));
CREATE TABLE app_user (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, nombre text NOT NULL, password_hash text NOT NULL, rol text NOT NULL DEFAULT 'admin' CHECK(rol IN ('admin','operador')), activo boolean NOT NULL DEFAULT true);
CREATE TABLE app_session (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES app_user(id), expires_at timestamptz NOT NULL);
CREATE INDEX ON app_session(expires_at);
CREATE TABLE login_attempt (ip_hash text PRIMARY KEY, intentos integer NOT NULL, inicio timestamptz NOT NULL DEFAULT now());
CREATE TABLE movimiento (id uuid PRIMARY KEY, insumo_id integer REFERENCES insumo(id), producto_id integer REFERENCES producto(id), nombre text NOT NULL, tipo text NOT NULL CHECK(tipo IN ('entrada','salida','ajuste','eliminación')), entidad text NOT NULL CHECK(entidad IN ('materia','producto')), cantidad numeric(18,6) NOT NULL, unidad text NOT NULL, valor numeric(18,4) NOT NULL, fecha timestamptz NOT NULL DEFAULT now(), descripcion text NOT NULL, user_id uuid REFERENCES app_user(id), CHECK ((insumo_id IS NULL) <> (producto_id IS NULL)));
CREATE INDEX ON movimiento(fecha DESC);
CREATE TABLE produccion (id uuid PRIMARY KEY, producto_id integer NOT NULL REFERENCES producto(id), cantidad numeric(12,6) NOT NULL CHECK(cantidad>0), fecha timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES app_user(id));
CREATE TABLE produccion_insumo (produccion_id uuid REFERENCES produccion(id), insumo_id integer REFERENCES insumo(id), cantidad numeric(12,6) NOT NULL CHECK(cantidad>0), PRIMARY KEY(produccion_id,insumo_id));
CREATE TABLE venta (id uuid PRIMARY KEY, producto_id integer NOT NULL REFERENCES producto(id), unidades integer NOT NULL CHECK(unidades>0), precio_unitario numeric(10,2) NOT NULL CHECK(precio_unitario>=0), fecha timestamptz NOT NULL, user_id uuid NOT NULL REFERENCES app_user(id));
CREATE TABLE tarea (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES app_user(id), title varchar(120) NOT NULL, priority text NOT NULL CHECK(priority IN ('Alta','Media','Baja')), completed boolean NOT NULL DEFAULT false);
CREATE TABLE evento (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES app_user(id), title text NOT NULL, date date NOT NULL, time text NOT NULL DEFAULT '', tipo text NOT NULL DEFAULT 'recordatorio');
CREATE TABLE historial_valor (fecha date PRIMARY KEY DEFAULT current_date, materia_prima numeric(18,4) NOT NULL, producto_terminado numeric(18,4) NOT NULL);
CREATE VIEW inventario_reorden AS SELECT i.*,u.abreviatura unidad_medida,p.*,n.z,
 n.z*p.demanda_diaria*p.pct_desv_demanda*sqrt(p.tiempo_entrega_dias) stock_seguridad,
 p.demanda_diaria*p.tiempo_entrega_dias+n.z*p.demanda_diaria*p.pct_desv_demanda*sqrt(p.tiempo_entrega_dias) punto_reorden_exacto,
 greatest(0,p.demanda_diaria*(p.tiempo_revision_dias+p.tiempo_entrega_dias)+n.z*p.demanda_diaria*p.pct_desv_demanda*sqrt(p.tiempo_revision_dias+p.tiempo_entrega_dias)-p.inventario_actual) pedido_sugerido
 FROM insumo i JOIN unidad_medida u ON u.id=i.unidad_id JOIN parametro_inventario p ON p.insumo_id=i.id JOIN nivel_servicio n ON n.nivel=p.nivel_servicio;
INSERT INTO nivel_servicio VALUES(.95,1.64),(.90,1.282),(.99,2.326);
INSERT INTO configuracion VALUES('litros_base_pipa',10000,'Base semanal de Hoja3 E4'),('costo_litro_agua',.236,'Costo por litro de Hoja3 E5');
INSERT INTO schema_migration(version) VALUES('001');
COMMIT;
